<script setup lang="ts">
import { computed, ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { clearDiagnosticLogs, getDiagnosticLogs, type DiagnosticLog } from '../../api/diagnostics'
import { t } from '../../locales'
import '../../styles/app.scss'
const logs = ref<DiagnosticLog[]>([])
const filter = ref<'all' | 'failure'>('all')
const expandedId = ref('')
const visibleLogs = computed(() => filter.value === 'all' ? logs.value : logs.value.filter(x => x.outcome !== 'success'))
function refresh() { logs.value = getDiagnosticLogs() }
function clear() { clearDiagnosticLogs(); refresh() }
function time(value: number) { return new Date(value).toLocaleString('zh-CN', { hour12: false }) }
function statusLabel(entry: DiagnosticLog) { return entry.outcome === 'success' ? t('成功') : entry.outcome === 'network_error' ? t('网络错误') : entry.outcome === 'http_error' ? t('HTTP 错误') : t('接口失败') }
function sourceLabel(entry: DiagnosticLog) { return entry.failureSource === 'frontend' ? '前端构造/调用' : entry.failureSource === 'network' ? '网络传输' : entry.failureSource === 'http' ? 'HTTP 服务端' : entry.failureSource === 'business' ? '业务响应' : '请求成功' }
function formatValue(value: unknown) { if (value === undefined) return '（无）'; if (typeof value === 'string') return value; try { return JSON.stringify(value, null, 2) ?? String(value) } catch { return String(value) } }
function toggleDetail(id: string) { expandedId.value = expandedId.value === id ? '' : id }
function copyEntry(entry: DiagnosticLog) { uni.setClipboardData({ data: JSON.stringify(entry, null, 2), success: () => uni.showToast({ title: '已复制诊断信息', icon: 'none' }), fail: () => uni.showToast({ title: '复制失败', icon: 'none' }) }) }
onShow(refresh)
</script>
<template><view class="inner-page diagnostics-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('接口日志')}}</text></view><view class="inner-main"><view class="diagnostics-toolbar"><view class="inner-tabs"><text class="inner-tab" :class="{active:filter==='all'}" @click="filter='all'">{{t('全部')}}</text><text class="inner-tab" :class="{active:filter==='failure'}" @click="filter='failure'">{{t('仅失败')}}</text></view><button class="clear-logs" @click="clear">{{t('清空')}}</button></view><view v-if="!visibleLogs.length" class="inner-card empty-state">{{t('暂无接口日志')}}</view><view v-for="entry in visibleLogs" :key="entry.id" class="diagnostic-row" @click="toggleDetail(entry.id)"><view class="diagnostic-top"><text class="diagnostic-endpoint">{{entry.method}} {{entry.endpoint}}</text><view class="diagnostic-actions"><text class="diagnostic-status" :class="entry.outcome==='success'?'ok':'bad'">{{statusLabel(entry)}}</text><button class="copy-log" @click.stop="copyEntry(entry)">复制</button></view></view><view class="diagnostic-meta"><text>{{time(entry.time)}}</text><text v-if="entry.durationMs !== undefined">{{entry.durationMs}}ms</text><text v-if="entry.httpStatus">HTTP {{entry.httpStatus}}</text><text v-if="entry.code !== undefined">code {{entry.code}}</text></view><text v-if="entry.message" class="diagnostic-message">{{entry.message}}</text><view v-if="expandedId===entry.id" class="diagnostic-detail" @click.stop><view class="detail-field"><text class="detail-label">诊断归属</text><text class="detail-value">{{sourceLabel(entry)}}</text></view><view class="detail-field"><text class="detail-label">请求 URL</text><text class="detail-value">{{entry.requestUrl || entry.endpoint}}</text></view><view class="detail-field"><text class="detail-label">请求头</text><text class="detail-payload">{{formatValue(entry.requestHeaders)}}</text></view><view class="detail-field"><text class="detail-label">请求体</text><text class="detail-payload">{{formatValue(entry.requestBody)}}</text></view><view class="detail-field"><text class="detail-label">响应状态 / 业务码</text><text class="detail-value">HTTP {{entry.httpStatus ?? '—'}} / {{entry.code ?? '—'}}</text></view><view class="detail-field"><text class="detail-label">响应头</text><text class="detail-payload">{{formatValue(entry.responseHeaders)}}</text></view><view class="detail-field"><text class="detail-label">响应体</text><text class="detail-payload">{{formatValue(entry.responseBody)}}</text></view><view v-if="entry.errorDetail" class="detail-field"><text class="detail-label">错误详情</text><text class="detail-payload">{{entry.errorDetail}}</text></view><text class="detail-hint">点击卡片收起详情；复制会复制该请求的完整诊断 JSON。</text></view></view></view></view></template>
<style scoped>.diagnostics-toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:18rpx}.diagnostics-toolbar .inner-tabs{margin:0}.clear-logs{height:58rpx;padding:0 18rpx;border:1rpx solid var(--cf-line);border-radius:10rpx;background:#fff;color:var(--cf-down);font-size:21rpx;line-height:58rpx}.diagnostic-row{padding:20rpx;background:#fff;border:1rpx solid var(--cf-line);border-radius:12rpx}.diagnostic-row+.diagnostic-row{margin-top:12rpx}.diagnostic-top{display:flex;align-items:center;justify-content:space-between;gap:12rpx}.diagnostic-endpoint{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:22rpx;font-weight:700}.diagnostic-actions{display:flex;align-items:center;gap:12rpx}.diagnostic-status{flex:0 0 auto;font-size:21rpx}.diagnostic-status.ok{color:var(--cf-up)}.diagnostic-status.bad{color:var(--cf-down)}.diagnostic-meta{display:flex;flex-wrap:wrap;gap:14rpx;margin-top:9rpx;color:var(--cf-muted);font-size:19rpx}.diagnostic-message{display:block;margin-top:9rpx;color:var(--cf-down);font-size:21rpx;line-height:1.4;word-break:break-all}.copy-log{flex:none;height:48rpx;padding:0 14rpx;margin:0;border:1rpx solid var(--cf-line);border-radius:8rpx;background:var(--cf-surface);color:var(--cf-brand);font-size:20rpx;line-height:48rpx}.diagnostic-detail{margin-top:18rpx;padding:16rpx;border:1rpx solid var(--cf-line);border-radius:10rpx;background:var(--cf-input)}.detail-field+.detail-field{margin-top:14rpx}.detail-label{display:block;margin-bottom:6rpx;color:var(--cf-muted);font-size:19rpx;font-weight:700}.detail-value,.detail-payload{display:block;color:var(--cf-text);font-size:19rpx;line-height:1.5;white-space:pre-wrap;word-break:break-all}.detail-payload{max-height:420rpx;overflow:auto;font-family:monospace}.detail-hint{display:block;margin-top:14rpx;color:var(--cf-soft);font-size:17rpx}</style>
